import React from "react";
import "../css/login.css";
import { Link, useNavigate } from "react-router-dom";
import { FaPhoneAlt, FaArrowLeft, FaArrowRight } from "react-icons/fa";

class Login extends React.Component {
    constructor(props) {
        super(props);
        this.state = {
            step: "phone", // "phone" | "code"
            phone: "",
            error: "",
            code: ["", "", "", ""],
        };
        this.phoneRef = React.createRef();
        this.codeRefs = [
            React.createRef(),
            React.createRef(),
            React.createRef(),
            React.createRef(),
        ];
    }

    handlePhoneSubmit = (e) => {
        e.preventDefault();
        const phone = this.phoneRef.current.value.trim();
        const cleanPhone = phone.replace(/\D/g, "");

        if (cleanPhone.length === 11) {
            this.setState({ error: "", step: "code" });
        } else {
            this.setState({
                error: "شماره موبایل باید ۱۱ رقم باشد",
            });
            this.phoneRef.current.focus();
        }
    };

    handleCodeChange = (index, value) => {
        // فقط عدد وارد شود
        const digit = value.replace(/\D/g, "").slice(0, 1);
        const newCode = [...this.state.code];
        newCode[index] = digit;
        this.setState({ code: newCode });

        // حرکت به ورودی بعدی
        if (digit && index < 3) {
            this.codeRefs[index + 1].current.focus();
        }
    };

    handleCodeKeyDown = (index, e) => {
        // حرکت با کلید Backspace به ورودی قبلی
        if (e.key === "Backspace" && !this.state.code[index] && index > 0) {
            this.codeRefs[index - 1].current.focus();
        }
    };

    // در صورت نیاز، کد کامل را می‌توان با Paste پر کرد
    handleCodePaste = (e) => {
        const paste = e.clipboardData.getData("text").replace(/\D/g, "").slice(0, 4);
        if (paste.length === 4) {
            const newCode = paste.split("");
            this.setState({ code: newCode });
            // فوکوس روی آخرین ورودی
            this.codeRefs[3].current.focus();
        }
    };

    render() {
        const { step, error, code } = this.state;

        return (
            <main className="container mt-4 pt-5">
                <Link to={"/welcome/"} className="back-link">
                    <FaArrowRight size={18} />
                </Link>

                <div className="align-items-center position-fixed top-50 start-50 translate-middle">
                    <div className="login-box-login shadow text-center item-back boder p-4 rounded-5 d-flex justify-content-center align-items-center">
                        <div className="welcome-box">
                            <img src="../img/aaa.png" alt="logo" />

                            {step === "phone" ? (
                                // مرحله ورود شماره موبایل
                                <div className="mt-5">
                                    <form className="mt-4" onSubmit={this.handlePhoneSubmit}>
                                        <div className="custom-floating">
                                            <FaPhoneAlt className="custom-icon" />
                                            <input
                                                type="tel"
                                                id="phone"
                                                className={`custom-input ${error ? "is-invalid" : ""}`}
                                                placeholder=" "
                                                dir="rtl"
                                                ref={this.phoneRef}
                                                onChange={(e) => {
                                                    this.setState({ phone: e.target.value });
                                                    if (error) this.setState({ error: "" });
                                                }}
                                            />
                                            <label htmlFor="phone" className="custom-label">
                                                شماره موبایل
                                            </label>
                                        </div>
                                        {error && (
                                            <div className="text-danger text-end small mt-1">
                                                {error}
                                            </div>
                                        )}
                                        <button type="submit" className="custom-btn">
                                            ارسال کد
                                        </button>
                                    </form>
                                </div>
                            ) : (
                                // مرحله ورود کد تأیید (۴ رقمی)
                                <div className="mt-5">
                                    <p className="text-muted mb-3">کد تأیید را وارد کنید</p>
                                    <div
                                        className="d-flex justify-content-center gap-3"
                                        dir="ltr"
                                        onPaste={this.handleCodePaste}
                                    >
                                        {code.map((digit, index) => (
                                            <input
                                                key={index}
                                                type="text"
                                                maxLength="1"
                                                className="form-control text-center"
                                                style={{
                                                    width: "60px",
                                                    height: "70px",
                                                    fontSize: "2rem",
                                                    borderRadius: "12px",
                                                    border: "1px solid #ced4da",
                                                }}
                                                value={digit}
                                                ref={this.codeRefs[index]}
                                                onChange={(e) =>
                                                    this.handleCodeChange(index, e.target.value)
                                                }
                                                onKeyDown={(e) => this.handleCodeKeyDown(index, e)}
                                                autoFocus={index === 0}
                                            />
                                        ))}
                                    </div>
                                    <button
                                        className="custom-btn mt-4"
                                        onClick={() => {
                                            alert("کد وارد شده: " + code.join(""));
                                        }}
                                    >
                                        تأیید کد
                                    </button>
                                    <button
                                        className="btn btn-link mt-2"
                                        onClick={() =>
                                            this.setState({ step: "phone", code: ["", "", "", ""] })
                                        }
                                    >
                                        بازگشت به ویرایش شماره
                                    </button>
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            </main>
        );
    }
}

export default Login;
